CREATE FUNCTION lms.protect_last_super_admin() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $$
DECLARE
  was_active boolean := false;
  remains_active boolean := false;
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Cannot truncate application accounts';
  END IF;
  IF TG_OP <> 'INSERT' THEN
    was_active := OLD.role = 'super_admin' AND OLD.is_active AND OLD.deleted_at IS NULL;
  END IF;
  IF TG_OP <> 'DELETE' THEN
    remains_active := NEW.role = 'super_admin' AND NEW.is_active AND NEW.deleted_at IS NULL;
  END IF;
  IF was_active AND NOT remains_active THEN
    -- Atomic counter updates serialize concurrent removals. At repeatable read,
    -- competing updates fail serialization instead of using a stale count.
    UPDATE lms_private.authorization_state SET active_super_admins = active_super_admins - 1
    WHERE singleton AND active_super_admins > 1;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'Cannot remove or deactivate the last active Super Admin';
    END IF;
  ELSIF remains_active AND NOT was_active THEN
    UPDATE lms_private.authorization_state SET active_super_admins = active_super_admins + 1
    WHERE singleton;
    IF NOT FOUND THEN RAISE EXCEPTION 'Authorization state is missing'; END IF;
  END IF;
  RETURN NULL;
END;
$$;
